css:
.dmp-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dmp-root,.dmp-root *,.dmp-root *::before,.dmp-root *::after{box-sizing:border-box}
.dmp-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dmp-root img{display:block;border:0;max-width:none}
.dmp-root > [data-node-id]{will-change:transform}
.dmp-root [hidden]{display:none!important}
.dmp-root [data-sh-theme="light"]{display:none!important}
.dmp-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.dmp-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.dmp-root .n2921_1374{position:absolute;inset:24.15% 44.94% 72.14% 6.48%}
.dmp-root .nI2921_1374_690_1476{position:absolute;display:flex;inset:0;align-items:center;justify-content:center;container-type:size}
.dmp-root .x53{flex:none;height:100cqh;width:100cqw;transform:rotate(180deg)}
.dmp-root .x54{position:relative;width:100%;height:100%}
.dmp-root .x55{position:absolute;inset:-2.86% -0.83%}
.dmp-root .x56{display:block;max-width:none;width:100%;height:100%}
.dmp-root .nI2921_1374_690_1477{word-break:break-word;position:absolute;font-family:"Nanum Gothic","Pretendard",sans-serif;font-weight:700;inset:22.86% 1.67% 28.57% 1.67%;line-height:17px;font-style:normal;font-size:16px;text-align:center;color:var(--wa-text, #fff);width:116px;white-space:nowrap}
.dmp-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.dmp-root[data-theme="light"] [data-name="Badge/Critical"] p,.dmp-root[data-theme="light"] [data-name^="status-critical"] p,.dmp-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.dmp-root[data-theme="light"] [data-name="Badge/Major"] p,.dmp-root[data-theme="light"] [data-name^="status-major"] p,.dmp-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #8f3f00)!important;font-weight:600;white-space:nowrap}
.dmp-root[data-theme="light"] [data-name="Badge/Minor"] p,.dmp-root[data-theme="light"] [data-name^="status-minor"] p,.dmp-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #6b4d00)!important;font-weight:600;white-space:nowrap}
.dmp-root[data-theme="light"] [data-name="Badge/Warning"] p,.dmp-root[data-theme="light"] [data-name^="status-warning"] p,.dmp-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.dmp-root[data-theme="light"] [data-name="Badge/Normal"] p,.dmp-root[data-theme="light"] [data-name^="status-normal"] p,.dmp-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.dmp-root[data-theme="light"] [data-name="Button/Ack"] p,.dmp-root[data-theme="light"] [data-name="Button/Ack All"] p,.dmp-root[data-theme="light"] [data-name="Button/Reset"] p{color:var(--wa-text, #fff)!important}
.dmp-root [data-name="Header"] > [data-name="Bullet"]:has(> [data-name="Base"]){transform-origin:0 4px;transform:translate(4px,-4px) scaleY(0.8889)}
.dmp-root [data-name="Event Log"] [data-name="Toolbar"] [data-name="Bullet"] > [data-name]{translate:2px 0}
.dmp-root [data-name="Header"] > [data-name="Bullet"]:not(:has(> [data-name="Base"])){transform-origin:0 1.83px;transform:translate(2px,-4.17px) scaleY(0.8649)}
.dmp-root[data-theme="light"] [data-name="Nav"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 60%, transparent)!important}
.dmp-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.dmp-root[data-theme="light"] [data-name="Logo Group"] [data-name="Title"]{background-image:linear-gradient(to right,var(--wa-point, #1d4fc4),var(--wa-point, #3a7ee6))!important}
.dmp-root[data-theme="light"] [data-name="Clock"] [data-name="Time"]{background-image:linear-gradient(to top,var(--wa-point, #173f9e),var(--wa-point, #2e72dc) 86.843%)!important}
.dmp-root[data-theme="light"] [data-name="Symbol"] > [data-name="Shape"] img{opacity:.32;filter:saturate(.7)}
.dmp-root[data-theme="light"] :is([data-name="Floor Layer"],[data-name="Floor"] > [data-name="Part"]) > *{opacity:.18}
.dmp-root[data-theme="light"] [data-name="Floor"] img{opacity:.25}
.dmp-root[data-theme="light"] [data-name="Effect"] > * > *,.dmp-root[data-theme="light"] [data-name="Effect"] img{opacity:.45}
.dmp-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) img{content:normal!important}
.dmp-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) p{color:var(--wa-text, #fff)!important}
.dmp-root[data-theme="light"] [data-name="Button/Stop"]{background:var(--wa-point, #1668d4)!important}
.dmp-root[data-theme="light"] [data-name="Button/Own"]{background:var(--wa-point, #2d6bd6)!important}
.dmp-root[data-theme="light"] [data-name="Button/Ack"]{background:var(--wa-point, #24489f)!important}
.dmp-root[data-theme="light"] [data-name="Button/Select"]{background:var(--wa-point, #1f6fd8)!important}
.dmp-root[data-theme="light"] .nI2921_1374_690_1477{color:var(--wa-point, #0f2238)}
.dmp-root[data-theme="light"] [data-name="Header"] [data-name="Nav"]{background:transparent!important}
.dmp-root[data-theme="light"] [data-name="Header"]:has([data-name="Icon Logout"]) p[data-name="Value"]{background-image:linear-gradient(180deg,var(--wa-point, #1d4fc4) 40%,var(--wa-point, #0a8fd0))!important}
.dmp-root[data-theme="light"] :is([data-name="Divider/Title"],[data-name="Divider/Buttons"],[data-name="Divider/Section"]){left:6.99px!important;width:240.02px!important}
.dmp-root[data-theme="light"] [data-name="Diagram Image"] img{filter:invert(1) hue-rotate(180deg) saturate(1.6) contrast(1.35)}
